const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/incidents/alerts',
  qs: {
    incident_id: 'SOME_INTEGER_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    'filters[id]': 'SOME_ARRAY_VALUE',
    'filters[updated_at]': 'SOME_STRING_VALUE',
    'filters[incident_id]': 'SOME_ARRAY_VALUE',
    'filters[injury_id]': 'SOME_ARRAY_VALUE',
    'filters[recipient_id]': 'SOME_ARRAY_VALUE',
    'filters[severity_level_id]': 'SOME_ARRAY_VALUE',
    'filters[triggered_by_id]': 'SOME_ARRAY_VALUE',
    'filters[filing_type_id]': 'SOME_ARRAY_VALUE',
    sort: 'SOME_STRING_VALUE'
  },
  headers: {Authorization: 'Bearer REPLACE_BEARER_TOKEN'}
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/incidents/alerts?incident_id=SOME_INTEGER_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&filters%5Bid%5D=SOME_ARRAY_VALUE&filters%5Bupdated_at%5D=SOME_STRING_VALUE&filters%5Bincident_id%5D=SOME_ARRAY_VALUE&filters%5Binjury_id%5D=SOME_ARRAY_VALUE&filters%5Brecipient_id%5D=SOME_ARRAY_VALUE&filters%5Bseverity_level_id%5D=SOME_ARRAY_VALUE&filters%5Btriggered_by_id%5D=SOME_ARRAY_VALUE&filters%5Bfiling_type_id%5D=SOME_ARRAY_VALUE&sort=SOME_STRING_VALUE"),
    Headers =
    {
        { "Authorization", "Bearer REPLACE_BEARER_TOKEN" },
    },
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

